INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss jede If-Anweisung ein Else haben?', 2, '[{"text": "Nein", "correct": true, "because": "Else ist optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit If-Else?', 3, '[{"text": "Entscheidungen treffen", "correct": true, "because": "Verzweigt bei Bedingung"}, {"text": "Wiederholung steuern", "correct": false, "because": "Für Schleifen"}, {"text": "UI gestalten", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer If-Else-Struktur?', 5, '[{"text": "Bedingung", "correct": true, "because": "Steuert Verzweigung"}, {"text": "Codeblock", "correct": true, "because": "Definiert Aktion"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Datenbankzugriff", "correct": false, "because": "Kein Kernbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) If prüft nur eine Bedingung. b) Else ist immer erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Else optional"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer If-Else-Anweisung?', 4, '[{"text": "Bedingungslogik", "correct": false, "because": "Entscheidend für Ablauf"}, {"text": "Ausführungsblock", "correct": false, "because": "Definiert Reaktion"}, {"text": "Serverkonfiguration", "correct": true, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob If mehrere Bedingungen prüfen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Mit AND/OR kombinierbar"}, {"text": "Nein", "correct": false, "because": "Flexibel nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Syntax wähle ich für eine einfache If-Anweisung?', 3, '[{"text": "if (x > 0)", "correct": true, "because": "Prüft Bedingung"}, {"text": "while (x > 0)", "correct": false, "because": "Schleife, kein If"}, {"text": "for (x > 0)", "correct": false, "because": "Falsche Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet If-Else?', 5, '[{"text": "Klarheit", "correct": true, "because": "Logik strukturiert"}, {"text": "Flexibilität", "correct": true, "because": "Anpassbare Verzweigungen"}, {"text": "Wiederholung", "correct": false, "because": "Für Schleifen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) If-Else steigert Lesbarkeit. b) Es ist immer verschachtelbar. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) strukturiert, b) möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine If-Else-Anweisung?', 4, '[{"text": "Bedingung", "correct": false, "because": "Steuert Verzweigung"}, {"text": "Codeblock", "correct": false, "because": "Definiert Aktion"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann If ohne Else laufen?', 2, '[{"text": "Ja", "correct": true, "because": "Else ist optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Möglichkeiten habe ich mit If-Else?', 4, '[{"text": "Verzweigung", "correct": true, "because": "Bedingte Ausführung"}, {"text": "Alternative Aktion", "correct": true, "because": "Else definiert"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass If-Else die Performance senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kein signifikanter Einfluss"}, {"text": "Ja", "correct": false, "because": "Nur bei Übernutzung relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei If-Else?', 3, '[{"text": "Klare Bedingung", "correct": true, "because": "Sichert korrekte Logik"}, {"text": "Schnelle Definition", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) If-Else kann verschachtelt sein. b) Es ersetzt Schleifen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Schleifen separat"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei If-Else?', 5, '[{"text": "Verschachtelungskomplexität", "correct": true, "because": "Kann unübersichtlich werden"}, {"text": "Logikfehler", "correct": true, "because": "Falsche Bedingung"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei If-Else unwichtig?', 3, '[{"text": "Bedingungsprüfung", "correct": false, "because": "Kern der Struktur"}, {"text": "Ausführungslogik", "correct": false, "because": "Definiert Verhalten"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Else mehrere Bedingungen haben?', 3, '[{"text": "Nein", "correct": true, "because": "Nur If prüft Bedingungen"}, {"text": "Ja", "correct": false, "because": "Else ist Standardfall"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob If-Else für mehrere Fälle geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Else-If erweiterbar"}, {"text": "Nein", "correct": false, "because": "Flexibel nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für eine alternative Bedingung?', 4, '[{"text": "else if", "correct": true, "because": "Fügt weitere Prüfung hinzu"}, {"text": "while", "correct": false, "because": "Schleife, kein If"}, {"text": "break", "correct": false, "because": "Schleifensteuerung"}]');
